// upload.controller.ts
import {
    Controller,
    Post,
    UploadedFile,
    UseInterceptors,
    InternalServerErrorException,
    UnsupportedMediaTypeException,
} from "@nestjs/common"
import { FileInterceptor } from "@nestjs/platform-express"
import { StorageService } from "./storage.service"

const MAX_FILE_SIZE = 5 * 1024 * 1024 // 5 MB
const ALLOWED_MIMES = ["image/png", "image/jpeg", "application/pdf"]

@Controller("uploads")
export class UploadController {
    constructor(private readonly storageService: StorageService) {}

    @Post("avatar")
    @UseInterceptors(
        FileInterceptor("file", {
            limits: { fileSize: MAX_FILE_SIZE }, // 5 MB cap — correctly configured
            fileFilter: (_req, file, cb): void => {
                if (!ALLOWED_MIMES.includes(file.mimetype)) {
                    return cb(new UnsupportedMediaTypeException("Unsupported file type"), false)
                }
                cb(null, true)
            },
        }),
    )
    async uploadFile(@UploadedFile() file: Express.Multer.File) {
        try {
            const stored = await this.storageService.save(file)
            return { path: stored, size: file.size }
        } catch (error) {
            // Catches anything that goes wrong while persisting the file —
            // but as QA's report below shows, it never runs for an oversized upload.
            throw new InternalServerErrorException("Failed to process upload")
        }
    }
}

// http-exception.filter.ts — the app's ONLY registered exception filter
import { ArgumentsHost, Catch, ExceptionFilter, HttpException } from "@nestjs/common"
import { Response } from "express"

@Catch(HttpException)
export class HttpExceptionFilter implements ExceptionFilter {
    catch(exception: HttpException, host: ArgumentsHost): void {
        const response = host.switchToHttp().getResponse<Response>()
        const status = exception.getStatus()
        response.status(status).json({ statusCode: status, message: exception.message })
    }
}

// upload.module.ts
import { Module } from "@nestjs/common"
import { APP_FILTER } from "@nestjs/core"

@Module({
    controllers: [UploadController],
    providers: [
        StorageService,
        { provide: APP_FILTER, useClass: HttpExceptionFilter },
    ],
})
export class UploadModule {}

